export type JupStablePluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function jupStableProgram() {
  return <T extends JupStablePluginRequirements>(
    client: T,
  ): ExtendedClient<T, { jupStable: JupStablePlugin }> => {
    return extendClient(client, {
      jupStable: <JupStablePlugin>{
        accounts: {
          benefactor: addSelfFetchFunctions(client, getBenefactorCodec()),
          config: addSelfFetchFunctions(client, getConfigCodec()),
          operator: addSelfFetchFunctions(client, getOperatorCodec()),
          vault: addSelfFetchFunctions(client, getVaultCodec()),
        },
        instructions: {
          createBenefactor: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateBenefactorInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          createOperator: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateOperatorInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          createVault: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateVaultInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          deleteBenefactor: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getDeleteBenefactorInstruction(input),
            ),
          deleteOperator: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getDeleteOperatorInstruction({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          init: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          manageBenefactor: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getManageBenefactorInstruction(input),
            ),
          manageConfig: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getManageConfigInstruction(input),
            ),
          manageOperator: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getManageOperatorInstruction(input),
            ),
          manageVault: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getManageVaultInstruction(input),
            ),
          mint: (input) =>
            addSelfPlanAndSendFunctions(client, getMintInstructionAsync(input)),
          redeem: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRedeemInstructionAsync(input),
            ),
          withdraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawInstructionAsync(input),
            ),
        },
        pdas: {
          benefactor: findBenefactorPda,
          newOperator: findNewOperatorPda,
          vault: findVaultPda,
          operator: findOperatorPda,
          config: findConfigPda,
          authority: findAuthorityPda,
          eventAuthority: findEventAuthorityPda,
        },
        identifyAccount: identifyJupStableAccount,
        identifyInstruction: identifyJupStableInstruction,
        parseInstruction: parseJupStableInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
